/// <summary>
/// MPJ_22902_CustomerNumbering
/// </summary>
public class METCreateCustNumSeqDialog extends RunBase
{
    protected   Dialog          dialog;
    protected   DialogField     dlgCreateCustomer, dlgBusinessUnit, dlgState, dlgBusinessPrefix;
    private     METBusinessName metBusinessName;
    private     Integer         metState, metBusinessPrefix;
    protected   FormStringControl      businessUnit;
    protected   FormIntControl         state, businessPrefix;
    
}

Method.Source:
   /// <summary>
   /// calling the updateCustomerNumSeqRec method
   /// </summary>
   /// <param name = "_args">_args</param>
   /// <returns>Customer account number</returns>
    public static CustAccount main(Args _args)
    {
        METCreateCustNumSeqDialog           dialogCreateCustNumSeqDialog;
        FormRun                             formRun = _args.caller();
        CustTable                           custTable = _args.record();

        dialogCreateCustNumSeqDialog = new METCreateCustNumSeqDialog();

        if (dialogCreateCustNumSeqDialog.prompt())
        {
            dialogCreateCustNumSeqDialog.updateCustomerNumSeqRec(custTable);
        }
        else
        {
            formRun.close();
        }

        return custTable.AccountNum;
    }

    /// <summary>
    /// update the customer number sequence
    /// </summary>
    /// <param name = "_custTable">_custTable</param>
    private void updateCustomerNumSeqRec(CustTable _custTable)
    {
        NumberSequenceCode      numberSequence, numberSeq;
        RefRecId                numberseqcust = METBusinessUnit::find(metBusinessName, metState).NumberSequenceId;
        Integer                 businessPrefixValue = METBusinessUnit::find(metBusinessName, metState).BusinessPrefix;
        NumberSequenceTable     numberseqTable = NumberSequenceTable::find(numberseqcust);
        int                     checkDigit;

        if (METCustParameters::Find().BusinessUnit == NoYes::Yes)
        {
            numberSeq = NumberSeq::newGetNumFromId(numberseqTable.RecId).num();
            
            if (this.validateNumSeq(numberSeq))
            {
                numberSequence = int2Str(businessPrefixValue) + int2Str(metState) + numberSeq;
            
                METCheckDigitLogic checkDigitLogic = METBusinessUnit::find(metBusinessName, metState).CheckDigitLogic;

                if (checkDigitLogic == METCheckDigitLogic::PECCD1)
                {
                    checkDigit = METCheckDigitLogicHelper::getCheckDigit_One(numberSeq);
                }
                else if (checkDigitLogic == METCheckDigitLogic::PECCD2)
                {
                    checkDigit = METCheckDigitLogicHelper::getCheckDigit_Two(numberSeq);
                }
                else if (checkDigitLogic == METCheckDigitLogic::PECCD5)
                {
                    checkDigit = METCheckDigitLogicHelper::checkDigit_Five(numberSeq);
                }
            
                if(checkDigitLogic != METCheckDigitLogic::None)
                {
                    numberSequence =  numberSequence + int2Str(checkDigit);
                }
            }
        }
        else
        {
            RefRecId                numberseqcustHWE = METCustParameters::Find().NumberSequenceId;
            NumberSequenceTable     numberseqTableHWE = NumberSequenceTable::find(numberseqcustHWE);
            
            numberSeq = NumberSeq::newGetNumFromId(numberseqTableHWE.RecId).num();

            if (this.validateNumSeq(numberSeq))
            {
                if (METCustParameters::Find().CheckDigit == NoYes::Yes)
                {
                    checkDigit = METCheckDigitLogicHelper::checkDigit_HWE(numberSeq);
                    numberSequence =  numberSeq + int2Str(checkDigit);
                }
                else
                {
                    numberSequence =  numberSeq;
                }
            }
        }
        _custTable.selectForUpdate(true);
        _custTable.AccountNum =  numberSequence;
    }

    /// <summary>
    /// Validate the number sequence
    /// </summary>
    /// <param name = "_numberSeq">number sequence</param>
    /// <returns>boolean value</returns>
    public boolean validateNumSeq(NumberSequenceCode _numberSeq)
    {
        if (METCustParameters::Find().BusinessUnit == NoYes::Yes)
        {
            if (strLen(_numberSeq) != 5)
            {
                return checkFailed("@MET:METNumSeqValidation");
            }
        }
        else
        {
            if (strLen(_numberSeq) != 7)
            {
                return checkFailed("@MET:METNumSeqHWEValidation");
            }
        }

        return true;
    }

    /// <summary>
    /// Dialog method to capture runtime user inputs for customer details
    /// </summary>
    /// <returns>dialog</returns>
    public Object dialog()
    {
        dialog = super();
        dialog.caption("@SYS59934");

        dlgCreateCustomer        = dialog.addField(extendedTypeStr(CustAccount), "@SYS124832");
        dlgCreateCustomer.enabled(false);

        dlgBusinessUnit = dialog.addField(extendedTypeStr(METBusinessName), "@SYS313109");
        dlgBusinessUnit.registerOverrideMethod(methodStr(FormStringControl, lookup),methodStr(METCreateCustNumSeqDialog, businessUnitLookup), this);
        dlgBusinessUnit.registerOverrideMethod(methodStr(FormStringControl, modified),methodStr(METCreateCustNumSeqDialog, businessUnitModified), this);

        dlgBusinessPrefix = dialog.addField(extendedTypeStr(Integer), "@MET:METBusinessPrefix");
        dlgBusinessPrefix.registerOverrideMethod(methodStr(FormIntControl, lookup),methodStr(METCreateCustNumSeqDialog, businessPrefixLookup), this);
        dlgBusinessPrefix.registerOverrideMethod(methodStr(FormIntControl, modified),methodStr(METCreateCustNumSeqDialog, businessPrefixModified), this);

        dlgState = dialog.addField(extendedTypeStr(Integer), "@SYS181123");
        dlgState.registerOverrideMethod(methodStr(FormIntControl, lookup),methodStr(METCreateCustNumSeqDialog, stateLookup), this);

        FormBuildStringControl      businessUnitControl;
        FormBuildIntControl         stateControl, businessPrefixControl;

        businessUnitControl    = dlgBusinessUnit.control();
        stateControl           = dlgState.control();
        businessPrefixControl  = dlgBusinessPrefix.control();

        stateControl.showZero(NoYes::No);
        businessPrefixControl.showZero(NoYes::No);

        if (METCustParameters::Find().BusinessUnit == NoYes::Yes)
        {
            businessUnitControl.mandatory(true);
            stateControl.enabled(false);
            businessPrefixControl.enabled(false);
        }

        else
        {
            businessUnitControl.enabled(false);
            stateControl.enabled(false);
            businessPrefixControl.enabled(false);
        }
        return dialog;
    }

    /// <summary>
    /// Validate the controls
    /// </summary>
    /// <param name = "_calledFrom">_calledFrom</param>
    /// <returns>boolean value</returns>
    public boolean validate(Object _calledFrom = null)
    {
        boolean     ret;
        ret         = super(_calledFrom);

        businessUnit    = dlgBusinessUnit.control();
        state           = dlgState.control();
        businessPrefix  = dlgBusinessPrefix.control();
        
        if (METCustParameters::Find().BusinessUnit == NoYes::Yes)
        {
            if (businessUnit.valueStr() == METConstants::emptyString)
            {
                ret = checkFailed("@MET:METBusinessUnitValidate");
            }
            else if (!businessPrefix.value())
            {
                ret =  checkFailed("Please select the business prefix");
            }
            else if (!state.value())
            {
                ret =  checkFailed("@MET:METStateValidate");
            }
        }
        return ret;
    }

/// <summary>
/// Retrieves values from the dialog after it is completed.
/// </summary>
/// <returns>true if values are retrieved successfully; otherwise, false.</returns>
public boolean getFromDialog()
{
    boolean ret = true;
    if (dlgBusinessUnit)
    {
        metBusinessName     = dlgBusinessUnit.value();
        metState            = dlgState.value();
        metBusinessPrefix   = dlgBusinessPrefix.value();
    }
    
    return ret;
}

/// <summary>
/// get the business name
/// </summary>
/// <returns>BusinessName</returns>
public METBusinessName getBusinessName()
{
    metBusinessName = dlgBusinessUnit.value();
    return metBusinessName;
}

/// <summary>
/// get the state
/// </summary>
/// <returns>State</returns>
public Integer getState()
{
    metState        = dlgState.value();
    return metState;
}

/// <summary>
/// get the business prefix
/// </summary>
/// <returns>BusinessPrefix</returns>
public Integer getBusinessPrefix()
{
    metBusinessPrefix        = dlgBusinessPrefix.value();
    return metBusinessPrefix;
}

    /// <summary>
    /// Lookup for Business unit from METBusinessUnit table
    /// </summary>
    /// <param name = "_formControl">formcontrol</param>
    public void businessUnitLookup(FormStringControl _formControl)
    {
        SysTableLookup          tableLookup = SysTableLookup::newParameters(tableNum(METBusinessUnit), _formControl);
        Query                   query;
        QueryBuildDataSource    businessUnitQBDS;

        query = new Query();
        businessUnitQBDS = query.addDataSource(tableNum(METBusinessUnit));

        tableLookup.addLookupfield(fieldNum(METBusinessUnit, BusinessName));
        businessUnitQBDS.addGroupByField(fieldNum(METBusinessUnit, BusinessName));
        businessUnitQBDS.orderMode(OrderMode::GroupBy);

        tableLookup.parmQuery(query);
        tableLookup.parmUseLookupValue(false);
        tableLookup.performFormLookup();
    }

    /// <summary>
    /// Lookup for Business Prefix  from METBusinessUnit table
    /// </summary>
    /// <param name = "_formControl">formcontrol</param>
    public void businessPrefixLookup(FormIntControl _formControl)
    {
        SysTableLookup          tableLookup = SysTableLookup::newParameters(tableNum(METBusinessUnit), _formControl);
        Query                   query;
        QueryBuildDataSource    businessPrefixQBDS;

        query = new Query();
        businessPrefixQBDS = query.addDataSource(tableNum(METBusinessUnit));

        tableLookup.addLookupfield(fieldNum(METBusinessUnit, BusinessPrefix), true);
        businessPrefixQBDS.addGroupByField(fieldNum(METBusinessUnit, BusinessPrefix));
        businessPrefixQBDS.orderMode(OrderMode::GroupBy);
        businessPrefixQBDS.addRange(fieldNum(METBusinessUnit, BusinessName)).value(dlgBusinessUnit.value());

        tableLookup.parmQuery(query);
        tableLookup.parmUseLookupValue(false);
        tableLookup.performFormLookup();
    }

    /// <summary>
    /// Lookup for State  from METBusinessUnit table
    /// </summary>
    /// <param name = "_formControl">formcontrol</param>
    public void stateLookup(FormIntControl _formControl)
    {
        SysTableLookup          tableLookup = SysTableLookup::newParameters(tableNum(METBusinessUnit), _formControl);
        Query                   query;
        QueryBuildDataSource    stateQBDS, logisticsAddressStateQBDS;
        
        query = new Query();
        stateQBDS = query.addDataSource(tableNum(METBusinessUnit));

        tableLookup.addLookupfield(fieldNum(METBusinessUnit, StatePrefix));
        
        stateQBDS.addRange(fieldNum(METBusinessUnit, BusinessName)).value(dlgBusinessUnit.value());
        stateQBDS.addRange(fieldNum(METBusinessUnit, BusinessPrefix)).value(dlgBusinessPrefix.value());
        
        tableLookup.parmQuery(query);
        tableLookup.performFormLookup();
    }

    /// <summary>
    /// Modify the business unit control
    /// </summary>
    /// <param name = "_businessUnitControl">business unit</param>
    /// <returns>business prefix enabled/disabled</returns>
    public boolean businessUnitModified(FormStringControl _businessUnitControl)
    {
        boolean     ret = _businessUnitControl.modified();
        businessPrefix  = dlgBusinessPrefix.control();

        if (METCustParameters::Find().BusinessUnit == NoYes::Yes)
        {
            if (dlgBusinessUnit.value())
            {
                businessPrefix.enabled(true);
            }
            else 
            {
                businessPrefix.enabled(false);
            }
        }
        return ret;
    }

    /// <summary>
    /// Modify the business prefix control
    /// </summary>
    /// <param name = "_businessPrefixControl">business prefix</param>
    /// <returns>state control enabled/disabled</returns>
    public boolean businessPrefixModified(FormIntControl _businessPrefixControl)
    {
        boolean     ret = _businessPrefixControl.modified();
        state           = dlgState.control();

        if (METCustParameters::Find().BusinessUnit == NoYes::Yes)
        {
            if (dlgBusinessPrefix.value())
            {
                state.enabled(true);
            }
            else
            {
                state.enabled(false);
            }
        }
        return ret;
    }

/// <summary>
/// Run in the new session
/// </summary>
/// <returns>false</returns>
protected boolean canRunInNewSession()
{
    return false;
}

/// <summary>
/// Construct the METCreateCustNumSeqDialog
/// </summary>
/// <returns>METCreateCustNumSeqDialog</returns>
public static METCreateCustNumSeqDialog construct()
{
    return new METCreateCustNumSeqDialog();
}
